namespace Core;require_once __DIR__.'/Guard.php';ml_guard_shield(__FILE__);class Config{private static $cfg=null;private static $base=null;public static function load(){if(self::$cfg!==null){return self::$cfg;}$file=__DIR__.'/../config/config.php';if(!file_exists($file)){http_response_code(500);header('Content-Type: application/json; charset=utf-8');echo json_encode(array('error'=>'config.php missing, run: php tools/install-cli.php'));exit;}$cfg=require $file;if(!is_array($cfg)){$cfg=array();}self::$base=$cfg;self::$cfg=$cfg;self::applyOverlay();return self::$cfg;}private static function applyOverlay(){$file=__DIR__.'/Settings.php';if(!file_exists($file)){return;}require_once $file;if(!class_exists('\\Core\\Settings')){return;}$s=\Core\Settings::all();if(!$s){return;}if(!empty($s['tmdb_api_key'])){self::$cfg['tmdb']['api_key']=$s['tmdb_api_key'];}if(!empty($s['adapters'])){$list=\Core\Settings::strToList($s['adapters']);if($list){self::$cfg['adapters']=$list;}}if(!empty($s['pan_types'])){$list=\Core\Settings::strToList($s['pan_types']);if($list){self::$cfg['pan_types']=$list;}}$syncMap=\Core\Settings::syncMap();$hasSync=false;foreach($syncMap as $k=>$child){if(!array_key_exists($k,$s)||$s[$k]===''){continue;}if(!$hasSync){if(!isset(self::$cfg['sync'])||!is_array(self::$cfg['sync'])){self::$cfg['sync']=array();}$hasSync=true;}self::$cfg['sync'][$child]=$s[$k];}$groupMaps=\Core\Settings::groupMaps();foreach($groupMaps as $section=>$map){$hit=false;foreach($map as $k=>$child){if(!array_key_exists($k,$s)||$s[$k]===''){continue;}if(!$hit){if(!isset(self::$cfg[$section])||!is_array(self::$cfg[$section])){self::$cfg[$section]=array();}$hit=true;}self::$cfg[$section][$child]=$s[$k];}}}public static function get($a,$b=null){$d=self::load();return(isset($d[$a])?$d[$a]:$b);}public static function sub($a,$b,$c=null){$d=self::load();if(isset($d[$a])&&is_array($d[$a])&&isset($d[$a][$b])){return $d[$a][$b];}return $c;}public static function base($a,$b=null){self::load();return(isset(self::$base[$a])?self::$base[$a]:$b);}public static function baseSub($a,$b,$c=null){self::load();if(isset(self::$base[$a])&&is_array(self::$base[$a])&&isset(self::$base[$a][$b])){return self::$base[$a][$b];}return $c;}public static function panTypes(){$c=self::load();if(isset($c['pan_types'])&&is_array($c['pan_types'])&&$c['pan_types']){return array_values($c['pan_types']);}$file=__DIR__.'/../config/pan_types.php';if(file_exists($file)){$list=require $file;if(is_array($list)&&$list){$out=array();foreach($list as $x){if(is_string($x)&&$x!==''){$out[]=$x;}}if($out){return $out;}}}return array('夸克','迅雷','光鸭','百度','UC');}}